"""Parse human-written money amounts without floating-point rounding."""

from decimal import Decimal, InvalidOperation
import re


def parse_amount(text: str) -> int:
    """Return integer cents, rounding ties away from zero.

    Surrounding whitespace, thousands commas, and a leading dollar sign
    are ignored. A leading sign may precede or follow the dollar sign.
    """
    if not isinstance(text, str):
        raise ValueError("Amount must be a numeric string")

    value = text.strip().replace(",", "")
    if value.startswith(("-$", "+$")):
        value = value[0] + value[2:]
    elif value.startswith("$"):
        value = value[1:]

    if not re.fullmatch(
        r"[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?",
        value,
    ):
        raise ValueError("Amount must be a finite number")

    try:
        amount = Decimal(value)
    except InvalidOperation as exc:
        raise ValueError("Amount must be a finite number") from exc
    if not amount.is_finite():
        raise ValueError("Amount must be a finite number")

    # Integer ratios avoid both binary floats and Decimal context precision
    # limits, including when the input has more than 28 significant digits.
    numerator, denominator = amount.as_integer_ratio()
    cents, remainder = divmod(abs(numerator) * 100, denominator)
    if (remainder * 2 > denominator):
        cents += 1
    return -cents if numerator < 0 else cents

