from ledgerkit.lines import line_total


def invoice_summary(lines, tax_rate_pct) -> dict:
    """Sum any iterable of lines and round tax halves away from zero."""
    subtotal = sum(line_total(*line) for line in lines)
    try:
        rate = Decimal(str(tax_rate_pct))
    except InvalidOperation as exc:
        raise ValueError("Tax rate must be a finite number") from exc
    if not rate.is_finite():
        raise ValueError("Tax rate must be a finite number")

    # Parse the rate's written decimal value, then use its exact ratio to
    # avoid binary floats and Decimal context precision limits.
    numerator, denominator = rate.as_integer_ratio()
    numerator *= subtotal
    denominator *= 100
    tax, remainder = divmod(abs(numerator), denominator)
    if (remainder * 2 > denominator):
        tax += 1
    if numerator < 0:
        tax = -tax

    return {"subtotal": subtotal, "tax": tax, "total": subtotal + tax}

"""Parse individual log records."""

import re
from datetime import datetime, timezone


_HEADER = re.compile(
    r"([0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z) "
    r"([Dd][Ee][Bb][Uu][Gg]|[Ii][Nn][Ff][Oo]|[Ww][Aa][Rr][Nn]|[Ee][Rr][Rr][Oo][Rr]) "
    r"(\S+)"
)


def parse_line(line: str) -> dict | None:
    """Return a normalized record, or None for malformed input."""
    if not isinstance(line, str):
        return None

    header, separator, message = line.strip().partition(": ")
    if not separator or not message.strip():
        return None
    match = _HEADER.fullmatch(header)
    if match is None:
        return None

    timestamp, level, component = match.groups()
    try:
        ts = datetime.strptime(timestamp, "%Y-%m-%dT%H:%M:%SZ").replace(
            tzinfo=timezone.utc
        )
    except ValueError:
        return None

    return {
        "ts": ts,
        "level": (level),
        "component": component,
        "message": message.strip(),
    }

