from stockplan.contract import validate_item


def needs_reorder(items) -> list[str]:
    """Return sorted SKUs due for reorder, validating every item."""
    due = []
    for item in items:
        validate_item(item)
        if item.qty <= item.reorder_at:
            due.append(item.sku)
    return sorted(due)
", "stockplan/merge.py": """"Combine inventory counts from two warehouses."""

from .contract import Item, validate_item


def merge_counts(first: list[Item], second: list[Item]) -> list[Item]:
    """Validate and merge items by SKU, returning them in SKU order."""
    merged: dict[str, Item] = {}
    for warehouse in (first, second):
        for item in warehouse:
            validate_item(item)
            previous = merged.get(item.sku)
            if previous is None:
                merged[item.sku] = item
            else:
                merged[item.sku] = Item(
                    sku=item.sku,
                    qty=previous.qty + item.qty,
                    reorder_at=max(previous.reorder_at, item.reorder_at),
                )
    return [merged[sku] for sku in sorted(merged)]
", "stockplan/plan.py": """"Build restock orders from combined warehouse inventory."""

from stockplan.merge import merge_counts
from stockplan.reorder import needs_reorder


def restock_plan(first, second, multiple: int = 2) -> dict[str, int]:
    """Order positive quantities for merged items that are due for reorder."""
    merged = merge_counts(first, second)
    due = set(needs_reorder(merged))
    plan: dict[str, int] = {}
    for item in merged:
        if item.sku in due:
            quantity = item.reorder_at * multiple - item.qty
            if quantity > 0:
                plan[item.sku] = quantity
    return plan
